# region: digest
def digest(raw):
    out = []
    for tok in raw:
        s = tok.strip()
        if s.isdigit() and int(s) > 0:
            out.append(int(s))
    return out

# region: fold
def fold(xs, floor_=2):
    return [v for v in xs if v > floor_]

# region: shape
def shape(xs):
    return [v for v in xs if v % 2 == 0]

# region: sift
def sift(xs, floor_=2):
    return [v for v in xs if v >= floor_]

# region: render
def render(xs):
    n = len(xs)
    return {'n': n, 'mean': (sum(xs) / n) if n else 0.0, 'max': max(xs) if xs else 0}

# region: intake
def intake(summary):
    out = dict(summary)
    out['flags'] = sorted(k for k, v in summary.items() if isinstance(v, int) and v > 0)
    return out

# region: run
def run(raw):
    return intake(render(sift(shape(fold(digest(raw))))))

