import unittest
from program import run

class T(unittest.TestCase):
    def test_case_00(self):
        self.assertEqual(run(['3', '1', '2']), {'n': 1, 'mean': 2.0, 'max': 2, 'flags': ['max', 'n']})
    def test_case_01(self):
        self.assertEqual(run(['10', '0', '7', 'x']), {'n': 1, 'mean': 10.0, 'max': 10, 'flags': ['max', 'n']})
    def test_case_02(self):
        self.assertEqual(run([' 5 ', '-2', '8']), {'n': 1, 'mean': 8.0, 'max': 8, 'flags': ['max', 'n']})
    def test_case_03(self):
        self.assertEqual(run(['4:2', '9:1', 'bad']), {'n': 0, 'mean': 0.0, 'max': 0, 'flags': []})
    def test_case_04(self):
        self.assertEqual(run(['12', '12', '1']), {'n': 2, 'mean': 12.0, 'max': 12, 'flags': ['max', 'n']})
    def test_case_05(self):
        self.assertEqual(run(['0']), {'n': 0, 'mean': 0.0, 'max': 0, 'flags': []})
    def test_case_06(self):
        self.assertEqual(run(['6', '6', '6', '6']), {'n': 4, 'mean': 6.0, 'max': 6, 'flags': ['max', 'n']})
    def test_case_07(self):
        self.assertEqual(run(['2', 'hello', '40']), {'n': 2, 'mean': 21.0, 'max': 40, 'flags': ['max', 'n']})

if __name__ == '__main__':
    unittest.main()
